   -- pragma synthesis_on


begin
   -- Architecture concurrent statements
   -- HDL Embedded Text Block 1 eb1
   reset_audio <= reset or buttons_s(0);                                

   -- HDL Embedded Text Block 2 tristate_pin1
   --bidirectional port sda
   sda_i <= sda;
   --tristate enable is active low
   sda <= sda_o when sda_t = '0' else 'Z';                                   

   -- HDL Embedded Text Block 3 buzzer_selection
   process(clk)
   begin
      if rising_edge(clk) then
          if buzzer_select = "00"  then
               buzzer_tmp <= buzzer_wave & not buzzer_wave;  
          elsif buzzer_select = "01" then
               buzzer_tmp <= buzzer_reg & not buzzer_reg;
           elsif buzzer_select = "10" then
               buzzer_tmp <= buzzer_morse & not buzzer_morse;
         end if;
      end if;
   end process;
   buzzer <= buzzer_tmp;
                             

   -- HDL Embedded Text Block 4 eb2
   identifier <= X"00000003";                                      

   -- HDL Embedded Text Block 5 pmod_port
   -- Pmod - Debug Outputs ----------------
   process(clk)
   begin
      if rising_edge(clk) then
         if pmod_o_select = '0' then
             pmod_jc <= pmod_o;
             pmod_jc <= dma_rdata32(7 downto 0);
        else   
             pmod_jc(0) <=  dma_rd;
             pmod_jc(1) <=  dma_rd_stb;
             pmod_jc(2) <=  dma_rd_en;
             pmod_jc(3) <=  sample_en; --ledstrip_timer;
             pmod_jc(4) <=  leds(0);
             pmod_jc(7 downto 6) <= (others => '0');   
         end if;
      end if;
   end process;      
                        

   -- HDL Embedded Text Block 6 const_values1
   hi <= '1';
   lo <= '0';   
                              

   -- HDL Embedded Text Block 7 tristate_pin3
   --bidirectional port sda 
   sda_i1 <= '0' when sda1 = '0' else '1';
   --tristate enable is active low
   sda1 <= sda_o1 when sda_t1 = '0' else 'Z';                                   

   -- HDL Embedded Text Block 8 audio_mux
   -- audio_in_multiplexer
   audio_right <= audio_in_right when audio_select= '0' else fxgen_wav_right & X"00";                            
   audio_left <= audio_in_left  when audio_select = '0' else fxgen_wav_left & X"00";    
    

   -- HDL Embedded Text Block 9 dma_rd_control1
   --- dma read control signals
   dma_rd_addr <= (others => '0');  
   dma_rd_request_size <= (others => '0');   
   dma_rd_mode <= "000" & dma_rd_en;   
   
   --dma rd feedback from dma_bridge
   dma_rdptr <= dma_rd_fb(31 downto 0);   
      
                         
   
   
   

   -- HDL Embedded Text Block 10 eb3
   -- eb3 10            
   audio_to_cpu <= audio_left(23 downto 8) & audio_envelope(15 downto 4) & buttons(0) &  light_barrier_2 & light_barrier_1 & buzzer_tmp(1);                            

   -- HDL Embedded Text Block 11 light_barrier_mux
   ----synchronize external gpio inputs and select---
   process(clk)
   begin
      if rising_edge(clk) then
          gpio_s <= gpio_i;   -- first sync stage
          for i in 0 to 7 loop
               if i = light_barrier_1_mux then
                   light_barrier_1 <= gpio_s(i);
               end if;
               if i = light_barrier_2_mux then
                   light_barrier_2 <= gpio_s(i);
               end if;
           end loop;
      end if;
   end process;
                                          

   -- HDL Embedded Text Block 12 led_mux
   leds <= leds_tmp when speed_trap_en = '0' else speed_trap_state;                                  

   -- HDL Embedded Text Block 13 eb5
   dma_wr_en <= dma_wr_en_reg or  dma_wr_en_sounding;                                 

   -- HDL Embedded Text Block 14 gpio_bidir
   --bidirectional port gpio
   gpio_i <= gpio;
   --tristate enable is active low ... rule by Vivado
   process(gpio_o,gpio_t)
   begin
      for i in  0 to 7 loop
         gpio(i) <= gpio_o(i) when gpio_t(0) = '0' else 'Z';
      end loop;
   end process;                                   

   -- HDL Embedded Text Block 15 eb6
   audio_fifo_in <= audio_in_left(23 downto 8) & audio_in_right(23 downto 8);                                 

   -- HDL Embedded Text Block 16 eb7
   -- eb7 16 
   process(fifo2_waddr_tx)
   begin
      fifo2_tx_waddr <= (others => '0');   
      fifo2_tx_waddr(fifo2_waddr_tx'range) <= fifo2_waddr_tx;     
   end process;
     
   process(fifo2_waddr_rx)
   begin
      fifo2_rx_waddr <= (others => '0');   
      fifo2_rx_waddr(fifo2_waddr_rx'range) <= fifo2_waddr_rx;     
   end process;                                  

   -- HDL Embedded Text Block 17 eb8
   fifo2_nreset <= not fifo2_reset;                                       

   -- HDL Embedded Text Block 25 dma_wr_control1
    -- dma write control signals          
   dma_wr_addr <= (others => '0');  
   dma_wr_request_size <= (others => '0');   
   dma_wr_mode <= "000" & dma_wr_en;        
   --dma rd feedback
   dma_wrptr <= dma_wr_fb(31 downto 0);     
             
   
   
   

   -- HDL Embedded Text Block 26 eb4
   dma_wdata32 <= audio_to_cpu when dma_wr_select = "00" else  dma_testpattern;   
   dma_rd_stb <= dma_stb when dma_rd_sampling =   '0' else sample_en;
   dma_wr_stb <= dma_stb when dma_wr_sampling =   '0' else  sample_en;


   -- Instance port mappings.
   U_5 : audio_dsp
      port map (
         audio_left      => audio_left,
         audio_right     => audio_right,
         clk             => clk,
         dump            => dsp_dump,
         dump_sel        => dsp_dump_sel,
         dump_stb        => dsp_dump_stb,
         reset           => reset,
         sample_en       => sample_en,
         scale           => dsp_scale,
         audio_dsp_left  => audio_dsp_left,
         audio_dsp_right => audio_dsp_right,
         led_bar         => ledstrip_bar,
         sig_pwm_in      => sig_pwm_in,
         val_envelope    => audio_envelope
      );
