         sample_en_o     => sample_en,
         scl             => scl,
         sda_o           => sda_o,
         sda_t           => sda_t
      );
   U_22 : comp_dds
      generic map (
         nbits_g => 30
      )
      port map (
         fcw        => dma_rate_fcw,
