         dds_strobe => dma_stb,
         dds_wave   => open
      );
   U_23 : comp_dds
      generic map (
         nbits_g => 27
      )
      port map (
         fcw        => buzzer_fcw,
         reset      => buzzer_dds_reset,
         enable     => hi,
         clk        => clk,
         dds_strobe => open,
         dds_wave   => buzzer_wave
      );
   U_24 : comp_dds
      generic map (
         nbits_g => 27
      )
      port map (
         fcw        => morse_fcw,
         reset      => morse_code,
         enable     => hi,
         clk        => clk,
         dds_strobe => open,
         dds_wave   => buzzer_morse
      );
   U_0 : comp_signal_synchr
      generic map (
         simulation_g => simulation_g
      )
      port map (
         buttons      => buttons,
